#!/usr/bin/env bash
# Open an SSH local forward to the sketchup-mcp server inside the Windows VM.
#
# The MCP server binds 127.0.0.1:9877 *inside the guest* (upstream bind, kept on
# purpose). Instead of widening that bind, we tunnel it over the authenticated
# SSH session: host 127.0.0.1:${MCP_LOCAL_PORT} -> guest 127.0.0.1:9877.
#
# Requires the guest sshd (port 2222 on the host) and the host key at
# integration/shared/ssh/host_key (generated by the OEM setup, git-ignored).
#
# Usage:
#   integration/scripts/mcp_tunnel.sh          # start (background), prints the port
#   integration/scripts/mcp_tunnel.sh stop     # stop the tunnel
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
KEY="$ROOT/integration/shared/ssh/host_key"
SSH_PORT="${VM_SSH_PORT:-2222}"
MCP_LOCAL_PORT="${MCP_LOCAL_PORT:-9878}"
GUEST_MCP_PORT=9877

if [[ "${1:-}" == "stop" ]]; then
    pkill -f "ssh .*-L 127.0.0.1:${MCP_LOCAL_PORT}:127.0.0.1:${GUEST_MCP_PORT}" 2>/dev/null || true
    echo "MCP tunnel on ${MCP_LOCAL_PORT} stopped (if it was running)."
    exit 0
fi

if [[ ! -f "$KEY" ]]; then
    echo "ERROR: host key not found at $KEY" >&2
    exit 1
fi

# Idempotent: do nothing if the local port already accepts connections.
if (exec 3<>"/dev/tcp/127.0.0.1/${MCP_LOCAL_PORT}") 2>/dev/null; then
    echo "MCP tunnel already up on 127.0.0.1:${MCP_LOCAL_PORT}"
    exit 0
fi

ssh -i "$KEY" -p "$SSH_PORT" \
    -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \
    -o BatchMode=yes -o ExitOnForwardFailure=yes \
    -f -N -L "127.0.0.1:${MCP_LOCAL_PORT}:127.0.0.1:${GUEST_MCP_PORT}" \
    Docker@127.0.0.1

sleep 1
if (exec 3<>"/dev/tcp/127.0.0.1/${MCP_LOCAL_PORT}") 2>/dev/null; then
    echo "MCP tunnel up: 127.0.0.1:${MCP_LOCAL_PORT} -> guest 127.0.0.1:${GUEST_MCP_PORT}"
else
    echo "ERROR: tunnel did not come up" >&2
    exit 1
fi
